using System;
using Game.Components;
using Game.Constants;
using Game.Data;
using Game.Systems.Path;
using Game.Systems.Stats;
using Game.Utils;
using Game.CodeGen;
using KL.Grid;
using KL.Randomness;
using KL.Utils;
using UnityEngine;
using Game.Systems.Drama;

namespace Game.Systems.AI {
    public sealed class AIActionFindTable : AIAction {
        [SelfInit]
        private static void Register() {
            // Raw key + .T() until Generated/T.cs is regenerated by the Unity editor;
            // matches how the codegen'd constant would resolve anyway.
            RegisterAction(new AIActionFindTable(ActIdEat,
                AIVarsH.IsHoldingFood, AIVarsH.IsReadyToEat, () => "nowhere.to.eat".T()));
            RegisterAction(new AIActionFindTable(ActIdDrink,
                AIVarsH.IsHoldingDrink, AIVarsH.IsReadyToDrink, () => "nowhere.to.drink".T()));
        }
        public const string ActIdEat = "FindTable";
        public const string ActIdDrink = "FindTableForDrink";
        public const string ActIdGame = "FindTableForGame";
        /// <summary>
        /// We will chat right after we sit, so don't start chatting before we sit
        /// </summary>
        public override SocialChatContext ChatContext => SocialChatContext.NoChat;
        // T constants get reassigned when translations load, so this has to stay
        // a Func<string> instead of a captured string.
        private readonly Func<string> noSpotT;
        private AIActionFindTable(string actId, int? precondition, int outcome,
                Func<string> noSpotT)
                : base(actId, () => T.VerbSearchingFor_V1.F(T.NounTable)) {
            this.noSpotT = noSpotT;
            if (precondition.HasValue) {
                Preconditions = AIState.With(precondition.Value, true);
            } else {
                Preconditions = AIState.With(outcome, false);
            }
            Outcomes = AIState.With(outcome, true);
            WithRequiredAbilities(AbilityIdH.Eat);
            MarkAsRest();
            MarkAsMobile();
        }

        private void Cleanup(AIAgentComp agent, AIGoal goal, bool activation) {
            var bb = agent.BB;
            bb.MoveTargetPos = 0;
            bb.MoveProgress = null;
            bb.ClearBlacklist();
            var isFailed = AIGoal.IsFailed(goal) || AIGoal.IsCancelled(goal);
            // #if !PRODUCTION_BUILD
            // D.Warn("AIActionFindTable cleanup: {0}, activation: {1}, failed: {2}",
            //     goal, activation, isFailed);
            // #endif
            if (activation || isFailed) {
                // the table we're eating at
                bb.UnreserveSlotSide(false);
                bb.RemoveOpportunity(agent.S);
            }

            if (!isFailed) {
                // D.Warn("Cleanup FindTable didn't fail. TargetEntity: {0}. Carrying: {1}. {2}",
                //     bb.TargetEntity, agent.Being.Graphics.Carrying, goal);
                return;
            // } else {
            //     D.Warn("Cleanup FindTable failed. TargetEntity: {0}. Carrying: {1}. {2}",
            //         bb.TargetEntity, agent.Being.Graphics.Carrying, goal);
            }

            // These are transferred to the next AI action, therefore
            // only cleaned on demand

            // meal obj
            if (agent.Being.Graphics.IsCarrying()) {
                if (bb.TargetEntity is Obj obj) {
                    obj.Pile?.ReaddToInventoryIfNeeded();
                }
                agent.Being.Graphics.DropIfCarrying();
            }
            bb.TargetEntity = null;
        }

        public override void OnActivate(AIAgentComp agent, AIGoal goal, long ticks) {
            Cleanup(agent, goal, true);
        }

        public override void OnDeactivate(AIAgentComp agent, AIGoal goal, long ticks) {
            Cleanup(agent, goal, false);
        }

        public void IgnoreTable(Slot slot, AIAgentComp agent) {
            agent.BB.AddToBlacklist(slot.Parent.EntityId);
        }

        public override AIActionResult Execute(GameState S, AIAgentComp agent,
                AIGoal goal, long ticks) {
            if (agent.Motion.IsBusy) {
                return InProgress;
            }
            if (agent.BB.MoveProgress == null) {
                // find table
                return FindTable(S, agent, goal, ticks);
            } else {
                // sit at table
                return UseTable(S, agent, goal, ticks);
            }
        }

        private void ApplyNoSpotPenalty(AIAgentComp agent, long ticks) {
            AddMentalEffect(agent, ticks, Consts.TicksPer4Hours, noSpotT(), -5);
        }

        /*
        S = slot, s = side position
           s s
        s [S S] s
           s s
        */
        private AIActionResult FindTable(GameState S, AIAgentComp agent, AIGoal goal,
                long ticks) {
            var worker = agent.Being;

            var bd = agent.BeingData;
            // How about not dying while trying to find a table
            if (bd.StatsBeing.Hunger.Value < 0.05f &&
                    bd.Safety.IsActuallySafeAtWithoutEquipment(agent.Motion.Position.Idx)) {
                // premature success, eat on the spot
                goal.WithWorld(AIVarsH.IsReadyToEat, true);
                return Success;
            }

            // Safety net - if we've been searching for this long, something is wrong
            // (e.g. permanently unreachable safe area). Fail instead of looping forever.
            if (agent.TicksInCurrentAction > Consts.TicksPer4Hours) {
                ApplyNoSpotPenalty(agent, ticks);
                return Failed(noSpotT());
            }

            // try closest non-expired opportunity
            var existingOP = S.Query.FindSocialOpportunity.Ask(
                agent.BeingData, SocialOpportunityIdH.Table);

            var slot = S.Sys.Slots.FindForFood(worker, agent.BB.Blacklist,
                    out var sideIdx, tryNearSlot: existingOP?.Slot);

            if (slot != null && agent.BB.Opportunity == null && !slot.Parent.IsMakeshift) {
                var op = SocialOpportunity.CreateFor(agent, slot,
                    SocialOpportunityIdH.Table, Consts.TicksPerHour);
                agent.BB.AddOpportunity(S, op);
            }

            // D.Warn("Found slot for food: {0} | {1}", slot, slot?.Parent.Tile);

            // couldn't find a table, even a makeshift one
            if (slot == null) {
                return FindRandomSpot(S, agent, goal, ticks);
            } else {
                if (agent.BB.TryReserveSlotSide(slot, sideIdx, goal)) {
                    agent.BB.MoveTargetPos = sideIdx;
                    if (!agent.Motion.TryGoTo(sideIdx, PathReqFlags.AdjOnTop,
                            out agent.BB.MoveProgress)) {
                        agent.BB.UnreserveSlotSide(true);
                        agent.Motion.StoreNavFailureAt(sideIdx);
                        IgnoreTable(slot, agent);
                    }
                }
                return InProgress;
            }
        }

        private AIActionResult UseTable(GameState S, AIAgentComp agent, AIGoal goal,
                long ticks) {
            // are we at the slot?
            var slot = agent.BB.ReservedSlot;
            var agentPos = agent.Motion.Position.Idx;

            // We don't have anything to use, let's just eat
            if (slot == null) {
                // Walk to the random spot failed, or it turned out unsafe by the time
                // we got there (e.g. environment changed mid-walk) - record it as a nav
                // failure so FindRandomSpot won't pick the same spot again.
                if (agent.BB.MoveProgress.HasFailed
                        || !agent.BeingData.Safety.IsActuallySafeAtWithoutEquipment(agentPos)) {
                    if (agent.BB.MoveTargetPos > 0) {
                        agent.Motion.StoreNavFailureAt(agent.BB.MoveTargetPos);
                    }
                    agent.BB.ClearMoveTarget();
                    return FindRandomSpot(S, agent, goal, ticks);
                }
                // D.Err("Unexpected, missing table! {0}", goal);
                goal.WithWorld(AIVarsH.IsReadyToEat, true);
                return Success;
            }

            var spotIdx = agent.BB.ReservedSideIdx;
            if (agentPos != spotIdx && !Pos.AreAdjacent(agentPos, spotIdx)) {
                if (!agent.BB.MoveProgress.HasFailed) {
                    // we're not at the spot!
                    D.Err("Agent is too far from the eat spot: {0}: {1}",
                        Pos.StringFromTo(agentPos, spotIdx), agent);
                }
                IgnoreTable(slot, agent);
                agent.BB.UnreserveSlotSide(true);
                agent.BB.ClearMoveTarget();
                // find another table
                return InProgress;
            }

            if (!agent.BeingData.Safety.IsActuallySafeAtWithoutEquipment(agentPos)) {
                IgnoreTable(slot, agent);
                agent.BB.UnreserveSlotSide(true);
                agent.BB.ClearMoveTarget();
                return InProgress;
            }

            var worker = agent.Being;
            var mealObj = worker.Graphics.Carrying;
            if (mealObj == null) {
                D.Warn("Expected to carry a meal, but no meal! Failing use table: {0}", goal);
                return Failed(T.AdRejInterrupted);
            }
            ServeOnTable(worker, slot, spotIdx, mealObj);
            // carry this over to the next ai action
            agent.BB.TargetEntity = mealObj;

            goal.WithWorld(AIVarsH.IsReadyToEat, true);
            return Success;
        }

        // Puts the carried meal down on the table in front of the being standing at spotIdx.
        // The meal stays out of the inventory, so nobody else takes it while it is eaten.
        public static void ServeOnTable(Being worker, Slot slot, int spotIdx, Entity meal) {
            var vertOff = Vector2.zero;
            // This is a lerp value
            float mealPosBias = 0.2f;
            // Worker is below
            if (Pos.N(spotIdx) == slot.SlotPosIdx) {
                vertOff = new(0, -0.02f);
                mealPosBias = 0f;
            } else if (Pos.S(spotIdx) == slot.SlotPosIdx) {
                // Worker is is above the meal
                mealPosBias = 0.25f;
            } else {
                // Spot is on the side
                vertOff = new(0, 0.2f);
            }

            worker.Motion.MoveNearbyAndFace(slot.SlotPosIdx);
            // Drop the meal so we can put it on the table.
            // True = will not complain about  not adding to inventory
            worker.Graphics.Drop(meal, true);

            if (meal is Obj o) {
                // Reposition the meal to be on the spot
                EntityUtils.PositionBetween(slot.ContainedPosition + vertOff,
                    worker.Position, o, mealPosBias);
            } else {
                D.Err("Meal is not Obj! {0}", meal);
            }
        }

        private AIActionResult FindRandomSpot(GameState S, AIAgentComp agent, AIGoal goal,
                long ticks) {
            agent.BB.UnreserveSlotSide(false);

            // Safety net - if we've been searching for this long, something is wrong
            // (e.g. permanently unreachable safe area). Fail instead of looping forever.
            if (agent.TicksInCurrentAction > Consts.TicksPer4Hours) {
                ApplyNoSpotPenalty(agent, ticks);
                return Failed(noSpotT());
            }

            // Search nearby regions for somewhere safe to take off the helmet and eat.
            // Must match the predicate UseTable() validates arrival with
            // (IsActuallySafeAtWithoutEquipment), or we'd walk somewhere, get rejected,
            // and search again forever.
            var isGrounded = agent.Motion.IsGrounded;
            var path = S.Sys.Path;
            var safety = agent.BeingData.Safety;
            var foundPos = S.Query.FindNearby.Ask(agent.PosIdx, isGrounded, 10, (p) => {
                if (p < 1 || agent.Motion.HadNavFailureAt(p)) {
                    return false;
                }
                return path.IsNavigable(p, isGrounded)
                    && safety.IsActuallySafeAtWithoutEquipment(p);
            });
            if (foundPos != Pos.Invalid) {
                agent.BB.MoveTargetPos = foundPos;
                if (agent.Motion.TryGoTo(foundPos, PathReqFlags.AdjOnTop,
                        out agent.BB.MoveProgress)) {
                    return InProgress;
                }
                agent.Motion.StoreNavFailureAt(foundPos);
            }
            ApplyNoSpotPenalty(agent, ticks);
            return Failed(noSpotT());
        }
    }
}
